export const FEEDBACK_COLUMNS = ["ID","Source","Brand","Sales Description","Country","Derivate (e-code)","Engine Type","Feedback Type","Customer Feedback","Vfc level2 3 Name","Vfc level2 Name","Vfc level3 Name","Source URL","Published At","Published Precision","Retrieved At","Language","Research Agent","Original Source ID","Original Record ID","Fundstelle / Kontextbezug","Source ID","Run IDs","Limitations"];
const original = (record:ResearchRecord,key:string):unknown => {
  const supplied=record.metadata.originalFields;
  return supplied && typeof supplied==="object" ? (supplied as Record<string,unknown>)[key] : record.metadata[key];
};
export function safeSpreadsheetText(value:unknown):string {
  const text=value==null?"":typeof value==="string"?value:typeof value==="object"?JSON.stringify(value):String(value);
  return /^[\s\u0000-\u001f]*[=+@-]/.test(text)?`'${text}`:text;
}
function feedbackRows(dataset:ResearchDataset):unknown[][] {
  const sources=new Map(dataset.sources.map((s)=>[s.id,s]));
  return dataset.records.filter((r)=>r.recordType==="feedback").flatMap((r)=>{
    const associations=Array.isArray(r.metadata.sourceClassifications)?r.metadata.sourceClassifications:[{}];
    return associations.map((association)=> {
      const category=association && typeof association==="object"?association as Record<string,unknown>:{};
      return [r.id,sources.get(r.sourceId)?.publisher??r.provider,original(r,"Brand")??"",original(r,"Sales Description")??"",r.marketAttribution?.value??original(r,"Country")??"",original(r,"Derivate (e-code)")??"",original(r,"Engine Type")??"",original(r,"Feedback Type")??"",r.text,category["Vfc level2 3 Name"]??original(r,"Vfc level2 3 Name")??"",category["Vfc level2 Name"]??original(r,"Vfc level2 Name")??"",category["Vfc level3 Name"]??original(r,"Vfc level3 Name")??"",r.originalUrl,r.publishedAt??"",r.datePrecision,r.retrievedAt,r.language??"",r.collectingAgents.join(", "),r.originalSourceId,r.originalRecordId,r.locator??r.parentId??r.threadId??"",r.sourceId,r.runIds.join(", "),r.limitations.join("\n")];
    });
  });
}
export function exportResearchJson(input:ResearchDataset):string { return JSON.stringify(ResearchDataset.parse(input),null,2); }
export function exportResearchCsv(input:ResearchDataset):string {
  const data=ResearchDataset.parse(input);
  const quote=(v:unknown)=>`"${safeSpreadsheetText(v).replaceAll('"','""')}"`;
