}
export async function exportResearchXlsx(input:ResearchDataset):Promise<Uint8Array> {
  const data=ResearchDataset.parse(input);const workbook=new ExcelJS.Workbook();
  const add=(name:string,headers:string[],rows:unknown[][])=>{
    const sheet=workbook.addWorksheet(name);
    sheet.addRow(headers);for(const row of rows)sheet.addRow(row.map(safeSpreadsheetText));
    sheet.views=[{state:"frozen",ySplit:1}];sheet.autoFilter={from:{row:1,column:1},to:{row:1,column:headers.length}};
    for(const column of sheet.columns)column.width=24;
    sheet.getRow(1).font={bold:true};sheet.eachRow((row)=>row.alignment={vertical:"top",wrapText:true});
  };
  add("Feedback_Explorer",FEEDBACK_COLUMNS,feedbackRows(data));
  add("Sources",["Source ID","Kind","Title","URL","Publisher","Published At","Retrieved At"],data.sources.map((s)=>[s.id,s.kind,s.title,s.uri,s.publisher,s.publishedAt,s.retrievedAt]));
  add("Research Records",["ID","Source ID","Record Type","Original Text","Original Source ID","Original Record ID","URL","Published At","Precision","Retrieved At","Language","Research Agents","Run IDs","Locator","Parent ID","Thread ID","Context","Metadata","Limitations"],data.records.map((r)=>[r.id,r.sourceId,r.recordType,r.text,r.originalSourceId,r.originalRecordId,r.originalUrl,r.publishedAt,r.datePrecision,r.retrievedAt,r.language,r.collectingAgents,r.runIds,r.locator,r.parentId,r.threadId,r.context,r.metadata,r.limitations]));
  add("Metrics Tables",["Record ID","Source ID","Original Headers","Original Row Values","Units","Footnotes","Dimensions"],data.records.filter((r)=>r.table).flatMap((r)=>r.table!.rows.map((row)=>[r.id,r.sourceId,r.table!.headers,row,r.table!.units,r.table!.footnotes,r.table!.dimensions])));
  add("Research Runs",["Run ID","Agent","Status","Record IDs","Requests","Limitations","Synthetic"],data.results.map((r)=>[data.runId,r.agentId,r.status,r.recordIds,r.requests,r.limitations,data.synthetic]));
  return new Uint8Array(await workbook.xlsx.writeBuffer());
}

