const HOSTS = new Set(["api.firecrawl.dev", "api.tavily.com", "www.googleapis.com", "youtube.googleapis.com", "api.apify.com", "api.x.com", "api.twitter.com", "www.reddit.com", "oauth.reddit.com", "api.openalex.org", "ec.europa.eu"]);
export function redactSecrets(value: string, secrets: readonly string[] = []): string {
  let result = value;
  for (const secret of secrets.filter(Boolean).sort((a,b) => b.length-a.length)) {
    result = result.split(secret).join("[REDACTED]");
    result = result.split(encodeURIComponent(secret)).join("[REDACTED]");
  }
