export async function withAbort<T>(work: Promise<T>, signal: AbortSignal): Promise<T> {
  if (signal.aborted) throw abortError(signal);
  let listener: () => void = () => {};
  try {
    return await Promise.race([work, new Promise<never>((_,reject) => {
      listener = () => reject(abortError(signal));
      signal.addEventListener("abort", listener, {once:true});
      if (signal.aborted) listener();
    })]);
  } finally { signal.removeEventListener("abort", listener); }
}
const delay = (ms: number, signal: AbortSignal) => withAbort(new Promise<void>((resolve) => { const timer = setTimeout(resolve,ms); timer.unref?.(); signal.addEventListener("abort",()=>clearTimeout(timer),{once:true}); }),signal);
export function createProviderHttp(options: {limits: ResearchLimits; signal: AbortSignal; fetchImpl?: typeof fetch}): ProviderHttp {
  let requests = 0, credits = 0, active = 0;
