  const cache = new Map<string, Promise<string>>();
  const signal = options.signal;
  const acquire = async () => {
    if (active >= options.limits.concurrency) await withAbort(new Promise<void>((resolve) => waiting.push(resolve)), signal);
    signal.throwIfAborted(); active++;
  };
  const release = () => { active--; waiting.shift()?.(); };
  function cost(url: URL, body: unknown): number {
    if (url.hostname === "api.firecrawl.dev") return url.pathname.endsWith("/search") ? 2 : options.limits.maxDocumentPages;
    if (url.hostname === "api.tavily.com") return url.pathname.endsWith("/search") ? 2 : Math.max(2, Array.isArray((body as {urls?:unknown[]})?.urls) ? Math.ceil((body as {urls:unknown[]}).urls.length/5)*2 : 2);
